      'ਤੁਸੀਂ ਸਾਡੇ API ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਕੀਮਤਾਂ ਵਿੱਚ ਯੋਗਦਾਨ ਪਾ ਸਕਦੇ ਹੋ।\nਜੇਕਰ ਤੁਸੀਂ ਪੈਮਾਨੇ \'ਤੇ ਕੀਮਤਾਂ ਵਿੱਚ ਯੋਗਦਾਨ ਪਾਉਣਾ ਚਾਹੁੰਦੇ ਹੋ, ਤਾਂ ਕਿਰਪਾ ਕਰਕੇ prices@openfoodfacts.org \'ਤੇ ਸਾਡੇ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।';

